INSERT INTO quiz_questions (id,curricular_unit_id,topic_id,prompt,image_url,explanation,difficulty,status,published_at,published_by,created_by,updated_by,created_at,updated_at) SELECT 'quiz-neuro-ap1-257',unit_id,'quiz-topic-neuro-ap1','Quantas fontanelas existem tipicamente no crânio neonatal?',NULL,'A membrana fibrosa na qual se forma a calota permanece não ossificada nos <strong>seis</strong> ângulos dos parietais, originando seis fontanelas: duas medianas únicas, anterior e posterior, e dois pares laterais, as fontanelas esfenoidais ou anterolaterais e mastoideias ou posterolaterais. A fontanela anterior é a maior, mede aproximadamente 4 cm no sentido anteroposterior e 2,5 cm transversalmente, situa-se na junção das suturas sagital, coronal e frontal e tem forma rombóide.<p><small>Gray’s Anatomy, 42.ª ed., p. 568.</small></p>','medium','published',unixepoch()*1000,actor_id,actor_id,actor_id,unixepoch()*1000,unixepoch()*1000 FROM _seed_neuro_ap1_context WHERE true ON CONFLICT(id) DO UPDATE SET curricular_unit_id=excluded.curricular_unit_id,topic_id=excluded.topic_id,prompt=excluded.prompt,image_url=NULL,explanation=excluded.explanation,difficulty=excluded.difficulty,status='published',published_at=COALESCE(quiz_questions.published_at,excluded.published_at),published_by=COALESCE(quiz_questions.published_by,excluded.published_by),archived_at=NULL,archived_by=NULL,deleted_at=NULL,deleted_by=NULL,updated_by=excluded.updated_by,updated_at=excluded.updated_at;
