INSERT INTO quiz_questions (id,curricular_unit_id,topic_id,prompt,image_url,explanation,difficulty,status,published_at,published_by,created_by,updated_by,created_at,updated_at) SELECT 'quiz-neuro-ap1-264',unit_id,'quiz-topic-neuro-ap1','Que suturas confluem na fontanela posterior?',NULL,'A fontanela anterior é a maior, mede aproximadamente 4 cm no sentido anteroposterior e 2,5 cm transversalmente, situa-se na junção das suturas sagital, coronal e frontal e tem forma rombóide. A fontanela posterior encontra-se na junção das suturas <strong>sagital e lambdóide</strong> e tem forma triangular. As fontanelas esfenoidal ou anterolateral e mastoideia ou posterolateral são pequenas, irregulares e localizam-se nos ângulos esfenoidal e mastoideu dos parietais, respetivamente.<p><small>Gray’s Anatomy, 42.ª ed., p. 568.</small></p>','hard','published',unixepoch()*1000,actor_id,actor_id,actor_id,unixepoch()*1000,unixepoch()*1000 FROM _seed_neuro_ap1_context WHERE true ON CONFLICT(id) DO UPDATE SET curricular_unit_id=excluded.curricular_unit_id,topic_id=excluded.topic_id,prompt=excluded.prompt,image_url=NULL,explanation=excluded.explanation,difficulty=excluded.difficulty,status='published',published_at=COALESCE(quiz_questions.published_at,excluded.published_at),published_by=COALESCE(quiz_questions.published_by,excluded.published_by),archived_at=NULL,archived_by=NULL,deleted_at=NULL,deleted_by=NULL,updated_by=excluded.updated_by,updated_at=excluded.updated_at;
