INSERT INTO quiz_questions (id,curricular_unit_id,topic_id,prompt,image_url,explanation,difficulty,status,published_at,published_by,created_by,updated_by,created_at,updated_at) SELECT 'quiz-neuro-ap1-272',unit_id,'quiz-topic-neuro-ap1','Qual é a última fontanela a encerrar?',NULL,'As fontanelas esfenoidal e posterior encerram cerca de 2–3 meses após o nascimento e a mastoideia perto do final do primeiro ano. A fontanela anterior apresenta maior variabilidade, mas <strong>a maioria encerra apenas por meados do segundo ano</strong>, sendo assim a última das principais fontanelas a encerrar habitualmente.<p><small>Gray’s Anatomy, 42.ª ed., p. 569.</small></p>','medium','published',unixepoch()*1000,actor_id,actor_id,actor_id,unixepoch()*1000,unixepoch()*1000 FROM _seed_neuro_ap1_context WHERE true ON CONFLICT(id) DO UPDATE SET curricular_unit_id=excluded.curricular_unit_id,topic_id=excluded.topic_id,prompt=excluded.prompt,image_url=NULL,explanation=excluded.explanation,difficulty=excluded.difficulty,status='published',published_at=COALESCE(quiz_questions.published_at,excluded.published_at),published_by=COALESCE(quiz_questions.published_by,excluded.published_by),archived_at=NULL,archived_by=NULL,deleted_at=NULL,deleted_by=NULL,updated_by=excluded.updated_by,updated_at=excluded.updated_at;
INSERT INTO quiz_question_options (id,question_id,option_text,position,is_correct) VALUES ('quiz-neuro-ap1-272-answer','quiz-neuro-ap1-272','Fontanela anterior',1,1);
INSERT INTO quiz_question_options (id,question_id,option_text,position,is_correct) VALUES ('quiz-neuro-ap1-272-incorrect','quiz-neuro-ap1-272','Resposta não correspondente',2,0);
INSERT INTO quiz_questions (id,curricular_unit_id,topic_id,prompt,image_url,explanation,difficulty,status,published_at,published_by,created_by,updated_by,created_at,updated_at) SELECT 'quiz-neuro-ap1-273',unit_id,'quiz-topic-neuro-ap1','Como é a calota neonatal quanto ao díploe?',NULL,'O nariz situa-se quase inteiramente entre as órbitas e o bordo inferior da abertura nasal encontra-se apenas ligeiramente abaixo dos pavimentos orbitários. <strong>Os ossos da calota são unilaminares e não possuem díploe.</strong> As eminências frontal e parietal são proeminentes e, na norma anterior, a maior largura do crânio situa-se entre as eminências parietais.<p><small>Gray’s Anatomy, 42.ª ed., p. 568.</small></p>','medium','published',unixepoch()*1000,actor_id,actor_id,actor_id,unixepoch()*1000,unixepoch()*1000 FROM _seed_neuro_ap1_context WHERE true ON CONFLICT(id) DO UPDATE SET curricular_unit_id=excluded.curricular_unit_id,topic_id=excluded.topic_id,prompt=excluded.prompt,image_url=NULL,explanation=excluded.explanation,difficulty=excluded.difficulty,status='published',published_at=COALESCE(quiz_questions.published_at,excluded.published_at),published_by=COALESCE(quiz_questions.published_by,excluded.published_by),archived_at=NULL,archived_by=NULL,deleted_at=NULL,deleted_by=NULL,updated_by=excluded.updated_by,updated_at=excluded.updated_at;
INSERT INTO quiz_question_options (id,question_id,option_text,position,is_correct) VALUES ('quiz-neuro-ap1-273-answer','quiz-neuro-ap1-273','Sem díploe',1,1);
INSERT INTO quiz_question_options (id,question_id,option_text,position,is_correct) VALUES ('quiz-neuro-ap1-273-incorrect','quiz-neuro-ap1-273','Resposta não correspondente',2,0);
INSERT INTO quiz_questions (id,curricular_unit_id,topic_id,prompt,image_url,explanation,difficulty,status,published_at,published_by,created_by,updated_by,created_at,updated_at) SELECT 'quiz-neuro-ap1-274',unit_id,'quiz-topic-neuro-ap1','Que apófise temporal está ausente no recém-nascido?',NULL,'O ouvido interno, a cavidade timpânica, os ossículos auditivos e o antro mastoideu têm já dimensões próximas das do adulto. A lâmina timpânica é ainda um anel incompleto que geralmente já começou a fundir-se com a parte escamosa, e a <strong>apófise mastoideia</strong> está ausente. O meato acústico externo é curto, reto e inteiramente cartilagíneo.<p><small>Gray’s Anatomy, 42.ª ed., p. 568.</small></p>','medium','published',unixepoch()*1000,actor_id,actor_id,actor_id,unixepoch()*1000,unixepoch()*1000 FROM _seed_neuro_ap1_context WHERE true ON CONFLICT(id) DO UPDATE SET curricular_unit_id=excluded.curricular_unit_id,topic_id=excluded.topic_id,prompt=excluded.prompt,image_url=NULL,explanation=excluded.explanation,difficulty=excluded.difficulty,status='published',published_at=COALESCE(quiz_questions.published_at,excluded.published_at),published_by=COALESCE(quiz_questions.published_by,excluded.published_by),archived_at=NULL,archived_by=NULL,deleted_at=NULL,deleted_by=NULL,updated_by=excluded.updated_by,updated_at=excluded.updated_at;
INSERT INTO quiz_question_options (id,question_id,option_text,position,is_correct) VALUES ('quiz-neuro-ap1-274-answer','quiz-neuro-ap1-274','Apófise mastoideia',1,1);
INSERT INTO quiz_question_options (id,question_id,option_text,position,is_correct) VALUES ('quiz-neuro-ap1-274-incorrect','quiz-neuro-ap1-274','Resposta não correspondente',2,0);
INSERT INTO quiz_questions (id,curricular_unit_id,topic_id,prompt,image_url,explanation,difficulty,status,published_at,published_by,created_by,updated_by,created_at,updated_at) SELECT 'quiz-neuro-ap1-275',unit_id,'quiz-topic-neuro-ap1','Como é o meato acústico externo no recém-nascido?',NULL,'A lâmina timpânica é ainda um anel incompleto que geralmente já começou a fundir-se com a parte escamosa, e a apófise mastoideia está ausente. <strong>O meato acústico externo é curto, reto e inteiramente cartilagíneo.</strong> A face externa da membrana timpânica orienta-se mais inferiormente do que lateralmente, em concordância com a configuração da base craniana.<p><small>Gray’s Anatomy, 42.ª ed., p. 568.</small></p>','medium','published',unixepoch()*1000,actor_id,actor_id,actor_id,unixepoch()*1000,unixepoch()*1000 FROM _seed_neuro_ap1_context WHERE true ON CONFLICT(id) DO UPDATE SET curricular_unit_id=excluded.curricular_unit_id,topic_id=excluded.topic_id,prompt=excluded.prompt,image_url=NULL,explanation=excluded.explanation,difficulty=excluded.difficulty,status='published',published_at=COALESCE(quiz_questions.published_at,excluded.published_at),published_by=COALESCE(quiz_questions.published_by,excluded.published_by),archived_at=NULL,archived_by=NULL,deleted_at=NULL,deleted_by=NULL,updated_by=excluded.updated_by,updated_at=excluded.updated_at;
INSERT INTO quiz_question_options (id,question_id,option_text,position,is_correct) VALUES ('quiz-neuro-ap1-275-answer','quiz-neuro-ap1-275','Curto, reto e cartilagíneo',1,1);
INSERT INTO quiz_question_options (id,question_id,option_text,position,is_correct) VALUES ('quiz-neuro-ap1-275-incorrect','quiz-neuro-ap1-275','Resposta não correspondente',2,0);
INSERT INTO quiz_questions (id,curricular_unit_id,topic_id,prompt,image_url,explanation,difficulty,status,published_at,published_by,created_by,updated_by,created_at,updated_at) SELECT 'quiz-neuro-ap1-276',unit_id,'quiz-topic-neuro-ap1','Que seios paranasais estão presentes ao nascimento?',NULL,'Ao nascimento estão presentes pequenos <strong>seios maxilares e etmoidais</strong>. O seio frontal é ainda essencialmente uma evaginação da cavidade nasal e não existe ainda pneumatização do corpo do esfenóide.<p><small>Gray’s Anatomy, 42.ª ed., cap. 39, p. 696; cap. 17, p. 291.</small></p>','medium','published',unixepoch()*1000,actor_id,actor_id,actor_id,unixepoch()*1000,unixepoch()*1000 FROM _seed_neuro_ap1_context WHERE true ON CONFLICT(id) DO UPDATE SET curricular_unit_id=excluded.curricular_unit_id,topic_id=excluded.topic_id,prompt=excluded.prompt,image_url=NULL,explanation=excluded.explanation,difficulty=excluded.difficulty,status='published',published_at=COALESCE(quiz_questions.published_at,excluded.published_at),published_by=COALESCE(quiz_questions.published_by,excluded.published_by),archived_at=NULL,archived_by=NULL,deleted_at=NULL,deleted_by=NULL,updated_by=excluded.updated_by,updated_at=excluded.updated_at;
INSERT INTO quiz_question_options (id,question_id,option_text,position,is_correct) VALUES ('quiz-neuro-ap1-276-answer','quiz-neuro-ap1-276','Maxilares e etmoidais',1,1);
INSERT INTO quiz_question_options (id,question_id,option_text,position,is_correct) VALUES ('quiz-neuro-ap1-276-incorrect','quiz-neuro-ap1-276','Resposta não correspondente',2,0);
INSERT INTO quiz_questions (id,curricular_unit_id,topic_id,prompt,image_url,explanation,difficulty,status,published_at,published_by,created_by,updated_by,created_at,updated_at) SELECT 'quiz-neuro-ap1-277',unit_id,'quiz-topic-neuro-ap1','Que fenómeno permite sobreposição óssea durante o parto?',NULL,'A porção do couro cabeludo que se encontra mais centralmente no canal de parto pode apresentar edema temporário, o caput succedaneum, devido a dificuldade do retorno venoso. <strong>As fontanelas, bem como a abertura e largura das suturas, permitem alguma sobreposição dos ossos da abóbada durante o nascimento: o crânio é comprimido num plano com alongamento compensatório no plano ortogonal.</strong> Estas deformações desaparecem durante a primeira semana após o nascimento.<p><small>Gray’s Anatomy, 42.ª ed., p. 568.</small></p>','medium','published',unixepoch()*1000,actor_id,actor_id,actor_id,unixepoch()*1000,unixepoch()*1000 FROM _seed_neuro_ap1_context WHERE true ON CONFLICT(id) DO UPDATE SET curricular_unit_id=excluded.curricular_unit_id,topic_id=excluded.topic_id,prompt=excluded.prompt,image_url=NULL,explanation=excluded.explanation,difficulty=excluded.difficulty,status='published',published_at=COALESCE(quiz_questions.published_at,excluded.published_at),published_by=COALESCE(quiz_questions.published_by,excluded.published_by),archived_at=NULL,archived_by=NULL,deleted_at=NULL,deleted_by=NULL,updated_by=excluded.updated_by,updated_at=excluded.updated_at;
INSERT INTO quiz_question_options (id,question_id,option_text,position,is_correct) VALUES ('quiz-neuro-ap1-277-answer','quiz-neuro-ap1-277','Abertura das suturas e fontanelas',1,1);
INSERT INTO quiz_question_options (id,question_id,option_text,position,is_correct) VALUES ('quiz-neuro-ap1-277-incorrect','quiz-neuro-ap1-277','Resposta não correspondente',2,0);
INSERT INTO quiz_questions (id,curricular_unit_id,topic_id,prompt,image_url,explanation,difficulty,status,published_at,published_by,created_by,updated_by,created_at,updated_at) SELECT 'quiz-neuro-ap1-278',unit_id,'quiz-topic-neuro-ap1','Até cerca de que idade a calota cresce lentamente após o primeiro ano?',NULL,'<strong>O crescimento da calota é rápido durante o primeiro ano e prossegue mais lentamente até aproximadamente ao sétimo ano</strong>, quando as suas dimensões já são quase adultas.<p><small>Gray’s Anatomy, 42.ª ed., pp. 568–569.</small></p>','medium','published',unixepoch()*1000,actor_id,actor_id,actor_id,unixepoch()*1000,unixepoch()*1000 FROM _seed_neuro_ap1_context WHERE true ON CONFLICT(id) DO UPDATE SET curricular_unit_id=excluded.curricular_unit_id,topic_id=excluded.topic_id,prompt=excluded.prompt,image_url=NULL,explanation=excluded.explanation,difficulty=excluded.difficulty,status='published',published_at=COALESCE(quiz_questions.published_at,excluded.published_at),published_by=COALESCE(quiz_questions.published_by,excluded.published_by),archived_at=NULL,archived_by=NULL,deleted_at=NULL,deleted_by=NULL,updated_by=excluded.updated_by,updated_at=excluded.updated_at;
