INSERT INTO quiz_questions (id,curricular_unit_id,topic_id,prompt,image_url,explanation,difficulty,status,published_at,published_by,created_by,updated_by,created_at,updated_at) SELECT 'quiz-neuro-ap1-279',unit_id,'quiz-topic-neuro-ap1','Que sincondrose mantém crescimento da base até à adolescência?',NULL,'O crescimento da base do crânio, responsável em grande parte pelo aumento do comprimento craniano, ocorre nas articulações cartilagíneas entre esfenóide e etmóide anteriormente e, sobretudo, entre esfenóide e occipital posteriormente. A maior parte deste crescimento ocorre nos primeiros cinco anos de vida, mas continua na <strong>sincondrose esfeno-occipital</strong> até à adolescência média. A persistência prolongada do crescimento desta região permite a erupção relativamente tardia da dentição permanente.<p><small>Gray’s Anatomy, 42.ª ed., pp. 569–570.</small></p>','medium','published',unixepoch()*1000,actor_id,actor_id,actor_id,unixepoch()*1000,unixepoch()*1000 FROM _seed_neuro_ap1_context WHERE true ON CONFLICT(id) DO UPDATE SET curricular_unit_id=excluded.curricular_unit_id,topic_id=excluded.topic_id,prompt=excluded.prompt,image_url=NULL,explanation=excluded.explanation,difficulty=excluded.difficulty,status='published',published_at=COALESCE(quiz_questions.published_at,excluded.published_at),published_by=COALESCE(quiz_questions.published_by,excluded.published_by),archived_at=NULL,archived_by=NULL,deleted_at=NULL,deleted_by=NULL,updated_by=excluded.updated_by,updated_at=excluded.updated_at;
INSERT INTO quiz_question_options (id,question_id,option_text,position,is_correct) VALUES ('quiz-neuro-ap1-279-answer','quiz-neuro-ap1-279','Sincondrose esfeno-occipital',1,1);
INSERT INTO quiz_question_options (id,question_id,option_text,position,is_correct) VALUES ('quiz-neuro-ap1-279-incorrect','quiz-neuro-ap1-279','Resposta não correspondente',2,0);
INSERT INTO quiz_questions (id,curricular_unit_id,topic_id,prompt,image_url,explanation,difficulty,status,published_at,published_by,created_by,updated_by,created_at,updated_at) SELECT 'quiz-neuro-ap1-280',unit_id,'quiz-topic-neuro-ap1','A partir de que ano se desenvolvem geralmente as apófises mastoideias?',NULL,'O espessamento da calota e o desenvolvimento das marcações musculares externas refletem a maturação musculoesquelética. As apófises mastoideias geralmente só se desenvolvem a partir do <strong>segundo ano</strong> e tornam-se pneumatizadas por volta do sexto ano.<p><small>Gray’s Anatomy, 42.ª ed., p. 569.</small></p>','medium','published',unixepoch()*1000,actor_id,actor_id,actor_id,unixepoch()*1000,unixepoch()*1000 FROM _seed_neuro_ap1_context WHERE true ON CONFLICT(id) DO UPDATE SET curricular_unit_id=excluded.curricular_unit_id,topic_id=excluded.topic_id,prompt=excluded.prompt,image_url=NULL,explanation=excluded.explanation,difficulty=excluded.difficulty,status='published',published_at=COALESCE(quiz_questions.published_at,excluded.published_at),published_by=COALESCE(quiz_questions.published_by,excluded.published_by),archived_at=NULL,archived_by=NULL,deleted_at=NULL,deleted_by=NULL,updated_by=excluded.updated_by,updated_at=excluded.updated_at;
INSERT INTO quiz_question_options (id,question_id,option_text,position,is_correct) VALUES ('quiz-neuro-ap1-280-answer','quiz-neuro-ap1-280','Segundo ano',1,1);
INSERT INTO quiz_question_options (id,question_id,option_text,position,is_correct) VALUES ('quiz-neuro-ap1-280-incorrect','quiz-neuro-ap1-280','Resposta não correspondente',2,0);
INSERT INTO quiz_questions (id,curricular_unit_id,topic_id,prompt,image_url,explanation,difficulty,status,published_at,published_by,created_by,updated_by,created_at,updated_at) SELECT 'quiz-neuro-ap1-281',unit_id,'quiz-topic-neuro-ap1','Por volta de que idade estão bem formadas as células mastoideias?',NULL,'Ao nascimento, as células mastoideias são apenas pequenos divertículos do antro. À medida que a mastóide se desenvolve no segundo ano, as células estendem-se progressivamente e estão <strong>bem formadas por volta do quarto ano</strong>, embora o maior crescimento ocorra na puberdade.<p><small>Gray’s Anatomy, 42.ª ed., cap. 42, secção “Mastoid air cells”.</small></p>','hard','published',unixepoch()*1000,actor_id,actor_id,actor_id,unixepoch()*1000,unixepoch()*1000 FROM _seed_neuro_ap1_context WHERE true ON CONFLICT(id) DO UPDATE SET curricular_unit_id=excluded.curricular_unit_id,topic_id=excluded.topic_id,prompt=excluded.prompt,image_url=NULL,explanation=excluded.explanation,difficulty=excluded.difficulty,status='published',published_at=COALESCE(quiz_questions.published_at,excluded.published_at),published_by=COALESCE(quiz_questions.published_by,excluded.published_by),archived_at=NULL,archived_by=NULL,deleted_at=NULL,deleted_by=NULL,updated_by=excluded.updated_by,updated_at=excluded.updated_at;
INSERT INTO quiz_question_options (id,question_id,option_text,position,is_correct) VALUES ('quiz-neuro-ap1-281-answer','quiz-neuro-ap1-281','Quarto ano',1,1);
